options.css:
*{box-sizing:border-box}html,body,#host{margin:0;width:100%;height:100%;overflow:hidden;background:#020812}.noc-dash{
  --bg:#020812;--panel:#06111d;--line:rgba(80,119,154,.34);--text:#f4f8fb;--muted:#b4c3cf;
  --red:#ff4c5c;--amber:#ffa526;--blue:#5b9cff;--green:#43cf83;
  width:100%;height:100%;min-height:720px;padding:15px 18px 16px;color:var(--text);overflow:hidden;
  background:#020812;
  font-family:Bahnschrift,"Segoe UI Variable Text","Segoe UI",Roboto,Arial,sans-serif;font-weight:500;letter-spacing:.005em;
}
.noc-header{height:58px;display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;border-bottom:1px solid rgba(81,119,151,.20);padding:0 2px 9px}.noc-demo-center{grid-column:2;justify-self:center;display:flex;align-items:center;justify-content:center;width:132px;height:48px}.noc-demo-logo{display:block;width:112px;max-height:44px;object-fit:contain}.noc-clock{grid-column:3;justify-self:end}
.noc-brand{display:flex;align-items:center;gap:0;min-width:0}.noc-brand>strong{font-size:32px;line-height:1;font-weight:700;letter-spacing:.055em}.noc-brand>i{display:block;width:2px;height:38px;background:#d08a34}.noc-brand>div{display:flex;flex-direction:column;gap:4px}.noc-brand b{font-size:16px;font-weight:700;letter-spacing:.04em}.noc-brand span{font-size:12px;color:#d2dbe2;font-weight:500}
.noc-clock{height:39px;min-width:206px;padding:0 10px;display:flex;align-items:center;gap:9px;border:1px solid rgba(84,123,158,.35);border-radius:5px;background:#04101b;color:#dce7ee;font-size:11px;letter-spacing:.02em}.noc-clock svg{width:18px;height:18px;fill:none;stroke:#64aaff;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.noc-clock>i{height:24px;width:1px;background:rgba(86,124,157,.28);margin-left:auto}.noc-clock .refresh-mark{width:17px;height:17px;stroke:#d7e6ef}
.noc-kpis{height:110px;display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;padding:12px 0 10px}.noc-kpi{min-width:0;height:88px;position:relative;display:flex;align-items:center;justify-content:center;border:1px solid var(--line);border-radius:7px;background:linear-gradient(145deg,rgba(7,20,34,.98),rgba(4,13,23,.98));padding:10px 72px;overflow:hidden}.kpi-icon{position:absolute;left:13px;top:50%;transform:translateY(-50%);width:56px;height:56px;display:grid;place-items:center;border:2px solid currentColor;border-radius:50%}.kpi-icon svg{width:34px;height:34px;fill:none;stroke:currentColor;stroke-width:1.65;stroke-linecap:round;stroke-linejoin:round}.kpi-body{min-width:0;width:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.kpi-body span{font-size:10px;font-weight:700;letter-spacing:.04em;white-space:nowrap;text-align:center}.kpi-body strong{font-size:28px;line-height:1.04;font-weight:700;margin-top:4px}.kpi-body small{font-size:9px;color:#d7dfe5;margin-top:5px;white-space:nowrap;text-align:center}.kpi-red{color:var(--red)}.kpi-amber{color:var(--amber)}.kpi-blue{color:var(--blue)}.kpi-green{color:var(--green)}.noc-kpi .kpi-body span,.noc-kpi .kpi-body small{color:#f4f8fb}
.streams-grid{height:calc(100% - 58px - 110px - 192px);min-height:430px;display:grid;grid-template-columns:1.02fr .99fr 1.10fr;gap:10px}.stream-card{min-width:0;min-height:0;display:grid;grid-template-rows:48px minmax(0,1fr);border-radius:7px;overflow:hidden}.stream-zabbix{border:1px solid rgba(255,76,92,.78);background:linear-gradient(145deg,rgba(53,11,20,.64),rgba(20,6,13,.92))}.stream-ope{border:1px solid rgba(91,156,255,.78);background:linear-gradient(145deg,rgba(8,34,62,.76),rgba(4,18,34,.94))}.stream-demo{border:1px solid rgba(67,207,131,.78);background:linear-gradient(145deg,rgba(4,53,33,.74),rgba(2,24,18,.95))}.stream-head{display:flex;align-items:center;justify-content:space-between;padding:0 15px;border-bottom:1px solid rgba(255,255,255,.11)}.stream-head strong{font-size:14px;font-weight:700;letter-spacing:.02em}.stream-head span{font-size:10px;font-weight:700}.stream-zabbix .stream-head span{color:var(--red)}.stream-ope .stream-head span{color:var(--blue)}.stream-demo .stream-head span{color:var(--green)}
.stream-list{min-height:0;display:grid;grid-template-rows:repeat(7,minmax(0,1fr));padding:0 8px}.stream-row{min-height:0;display:grid;align-items:center;border-bottom:1px solid rgba(210,229,241,.14);padding:7px 7px}.stream-row:last-child{border-bottom:0}.stream-row.empty-row{opacity:.16}.z-row{grid-template-columns:38px minmax(0,1fr)}.z-icon{width:31px;height:31px;display:grid;place-items:center;border:1px solid rgba(255,76,92,.45);border-radius:5px;background:rgba(255,255,255,.025);color:#d9dfe3}.z-icon svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.z-copy{min-width:0;display:grid;grid-template-rows:auto auto;gap:4px}.z-top,.z-bottom,.jira-top,.jira-bottom{min-width:0;display:flex;align-items:center;gap:8px}.z-top strong{min-width:0;font-size:12px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.sev-chip,.tag-chip,.status-chip{height:20px;display:inline-flex;align-items:center;justify-content:center;padding:0 7px;border:1px solid currentColor;border-radius:4px;font-size:8px;font-weight:700;white-space:nowrap;flex:0 0 auto}.sev-chip.high{color:#ffb31a}.sev-chip.disaster{color:#ff4c5c}.z-bottom .summary,.jira-summary{min-width:0;flex:1;font-size:10px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#f1f5f8}.row-time{font-size:9px;color:#d8e1e7;white-space:nowrap;flex:0 0 auto;font-variant-numeric:tabular-nums}.jira-row{display:grid;grid-template-rows:auto auto;gap:5px}.jira-top{align-items:flex-start}.jira-key{width:82px;flex:0 0 82px;color:var(--blue);font-size:11px;font-weight:700;text-decoration:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.stream-demo .jira-key{color:#4ae494}.jira-summary{font-size:10.4px;line-height:1.25;white-space:nowrap}.status-chip{max-width:155px;overflow:hidden;text-overflow:ellipsis;color:#dff2ff;border-color:#5f91bf;background:rgba(7,30,50,.28)}.stream-demo .status-chip{color:#e7fff1;border-color:#4b9b70;background:rgba(5,44,28,.30)}.jira-bottom{justify-content:space-between}.jira-meta{min-width:0;display:flex;align-items:center;gap:6px;overflow:hidden}.meta-text{max-width:180px;font-size:8.5px;color:#d4dfe5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tag-chip{height:18px;font-size:7.5px;color:#dce7ee;border-color:rgba(105,145,178,.45);background:rgba(4,15,25,.35)}.stream-demo .tag-chip{border-color:rgba(76,152,104,.50)}

/* V27 — divisões visuais das colunas nas 3 listas */
.stream-zabbix .z-top,.stream-zabbix .z-bottom{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:0}
.stream-zabbix .z-top strong,.stream-zabbix .z-bottom .summary{padding-right:12px;margin-right:12px;border-right:1px solid rgba(255,76,92,.22)}
.stream-zabbix .row-time{padding-left:12px}
.stream-zabbix .sev-chip{margin-left:0}
.stream-ope .jira-top,.stream-demo .jira-top{display:grid;grid-template-columns:92px minmax(0,1fr) auto;align-items:center;gap:0}
.stream-ope .jira-bottom,.stream-demo .jira-bottom{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:0}
.stream-ope .jira-key,.stream-demo .jira-key{width:auto;flex:initial;padding-right:12px;margin-right:12px;border-right:1px solid rgba(91,156,255,.22)}
.stream-demo .jira-key{border-right-color:rgba(67,207,131,.24)}
.stream-ope .jira-summary,.stream-demo .jira-summary{padding-right:12px;margin-right:12px;border-right:1px solid rgba(91,156,255,.18)}
.stream-demo .jira-summary{border-right-color:rgba(67,207,131,.20)}
.stream-ope .jira-meta,.stream-demo .jira-meta{padding-right:12px;margin-right:12px;border-right:1px solid rgba(91,156,255,.18)}
.stream-demo .jira-meta{border-right-color:rgba(67,207,131,.20)}
.stream-ope .row-time,.stream-demo .row-time{padding-left:12px}
.stream-zabbix .stream-row,.stream-ope .stream-row,.stream-demo .stream-row{position:relative}

.analytics-grid{height:192px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;padding-top:10px}.analytics-card{min-width:0;min-height:0;border:1px solid var(--line);border-radius:7px;background:linear-gradient(145deg,rgba(5,17,29,.99),rgba(3,12,21,.99));padding:12px 14px;overflow:hidden}.analytics-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;padding-bottom:6px}.analytics-head strong{font-size:12px;font-weight:700;letter-spacing:.02em}.analytics-head span{font-size:9px;color:#d6e0e7;white-space:nowrap}.analytics-head b{font-weight:600;color:#f4f8fb}.bar-list{height:calc(100% - 28px);display:flex;flex-direction:column;justify-content:space-evenly}.bar-row{min-width:0;display:grid;grid-template-columns:minmax(95px,1.15fr) minmax(90px,1fr) 72px;align-items:center;gap:8px}.bar-name{min-width:0;display:flex;align-items:center;gap:7px;font-size:9.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bar-name i{width:8px;height:8px;border-radius:1px;background:var(--c);flex:0 0 auto}.bar-track{height:9px;background:#0c1a27;border-radius:1px;overflow:hidden}.bar-fill{display:block;height:100%;width:var(--w);background:var(--c);transition:width .5s ease}.bar-row b{font-size:9px;font-weight:600;text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
.noc-dash.refresh-animate .noc-kpi,.noc-dash.refresh-animate .stream-card,.noc-dash.refresh-animate .analytics-card{animation:dashRefresh .6s ease both}.noc-dash.refresh-animate .stream-card{animation-delay:.08s}.noc-dash.refresh-animate .analytics-card{animation-delay:.14s}@keyframes dashRefresh{0%{opacity:.66;transform:translateY(2px)}100%{opacity:1;transform:none}}
@media(max-width:1400px){.noc-dash{padding:10px 12px 12px}.noc-header{height:54px}.noc-demo-center{width:112px;height:44px}.noc-demo-logo{width:96px;max-height:40px}.noc-brand>strong{font-size:28px}.noc-kpis{height:104px}.noc-kpi{height:84px;padding-left:64px;padding-right:64px}.kpi-icon{width:50px;height:50px}.kpi-body strong{font-size:25px}.streams-grid{height:calc(100% - 54px - 104px - 184px)}.analytics-grid{height:184px}.stream-head strong{font-size:12px}.jira-key{width:76px;flex-basis:76px}.jira-summary{font-size:9.5px}.bar-row{grid-template-columns:minmax(88px,1.1fr) minmax(75px,1fr) 62px}.bar-name{font-size:8.8px}}


/* ===== V26 | versão fiel ao conceito aprovado ===== */
.noc-brand b{font-size:20px;font-weight:700;letter-spacing:.025em;color:#f5f8fb}
.noc-brand>div{gap:0}.noc-brand span{display:none!important}
.kpi-purple{color:#a86df5}.kpi-purple .kpi-icon{border-color:#a86df5;background:rgba(168,109,245,.045)}.kpi-purple .kpi-body strong{color:#b37cf8}
.kpi-amber .kpi-body strong{color:#f7f9fb}.kpi-amber .kpi-body small{color:#ffd18a}
.kpi-blue .kpi-body strong{color:#68a5ff}.kpi-green .kpi-body strong{color:#4cdb8d}.kpi-red .kpi-body strong{color:#ff5364}
.important-host{color:#ffffff!important}.important-summary{color:#ffffff!important;font-weight:600!important}
.sev-chip.medium{color:#63a7ff}
.assignee-meta{display:inline-flex;align-items:center;gap:4px;min-width:0;max-width:220px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.assignee-meta em{font-size:7.5px;font-style:normal;color:#9fb2c1;font-weight:500;letter-spacing:.03em}
.assignee-meta strong{min-width:0;overflow:hidden;text-overflow:ellipsis;font-size:8.5px;color:#f5f8fb;font-weight:700}
.stream-demo .assignee-meta strong{color:#f2fff7}.assignee-meta.is-unassigned strong{color:#c7d3dc;font-weight:600}
.tag-chip.prio-critical{color:#ff6978;border-color:#ff4c5c;background:rgba(255,76,92,.12);box-shadow:inset 0 0 0 1px rgba(255,76,92,.07)}
.tag-chip.prio-high{color:#ffbf38;border-color:#d98b00;background:rgba(255,165,38,.11)}
.tag-chip.prio-medium{color:#76b2ff;border-color:#4d8ddd;background:rgba(91,156,255,.10)}
.tag-chip.prio-low{color:#62dc9b;border-color:#3aa76e;background:rgba(67,207,131,.09)}
.tag-chip.type-alert{color:#68e59f;border-color:#3db879;background:rgba(67,207,131,.08)}
.tag-chip.type-incident{color:#ffd15a;border-color:#c99a1a;background:rgba(255,196,60,.07)}
.tag-chip.type-request,.tag-chip.type-task{color:#78b6ff;border-color:#4e89c9;background:rgba(91,156,255,.08)}
.jira-key{font-size:11.5px!important}.jira-summary{font-size:10.6px!important}.status-chip{font-size:8px!important;font-weight:700!important}
.row-time{color:#eef3f7!important;font-weight:600!important}
.analytics-grid{height:192px}.analytics-card{background:#06111d}.bar-track{background:#0c1a27}.bar-fill{box-shadow:none}

/* V29 — SOMENTE divisões horizontais das linhas, mantendo todo o restante da V27 */
.stream-zabbix .stream-row:not(:last-child){border-bottom:1px solid rgba(255,92,104,.48)!important}
.stream-ope .stream-row:not(:last-child){border-bottom:1px solid rgba(91,156,255,.42)!important}
.stream-demo .stream-row:not(:last-child){border-bottom:1px solid rgba(67,207,131,.42)!important}


/* ===== V30 | COLUNAS RETAS E REALMENTE VISÍVEIS — SOMENTE NAS 3 LISTAS ===== */
.stream-card{grid-template-rows:48px 31px minmax(0,1fr)!important}
.stream-list{padding:0!important}
.column-head{min-width:0;display:grid;align-items:stretch;height:31px;border-bottom:1px solid rgba(255,255,255,.28);font-size:8.5px;font-weight:700;letter-spacing:.035em;color:#dce7ee;text-transform:uppercase;background:rgba(0,0,0,.10)}
.column-head>span{min-width:0;display:flex;align-items:center;padding:0 10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;border-right:1px solid currentColor}
.column-head>span:last-child{border-right:0;justify-content:center}
.z-column-head{grid-template-columns:40px minmax(120px,1.15fr) minmax(180px,1.85fr) 112px 92px;color:rgba(255,122,132,.68)}
.ope-column-head{grid-template-columns:94px minmax(220px,1fr) 108px 110px;color:rgba(112,174,255,.72)}
.demo-column-head{grid-template-columns:94px minmax(230px,1.45fr) minmax(165px,.82fr) 108px 132px;color:rgba(81,220,146,.72)}
.column-head>span{color:#dfe8ee}.z-column-head>span{border-right-color:rgba(255,122,132,.46)}.ope-column-head>span{border-right-color:rgba(112,174,255,.44)}.demo-column-head>span{border-right-color:rgba(81,220,146,.44)}

/* remove as divisões antigas por conteúdo para evitar linhas tortas/duplicadas */
.stream-zabbix .z-top strong,.stream-zabbix .z-bottom .summary,.stream-ope .jira-key,.stream-demo .jira-key,.stream-ope .jira-summary,.stream-demo .jira-summary,.stream-ope .jira-meta,.stream-demo .jira-meta{border-right:0!important;margin-right:0!important;padding-right:0!important}
.stream-ope .row-time,.stream-demo .row-time,.stream-zabbix .row-time{padding-left:0!important}

/* grade real por coluna — cada borda atravessa a linha inteira */
.z-grid-row{grid-template-columns:40px minmax(120px,1.15fr) minmax(180px,1.85fr) 112px 92px!important;padding:0!important;align-items:stretch!important}
.ope-grid-row{grid-template-columns:94px minmax(220px,1fr) 108px 110px!important;padding:0!important;align-items:stretch!important}
.demo-grid-row{grid-template-columns:94px minmax(230px,1.45fr) minmax(165px,.82fr) 108px 132px!important;padding:0!important;align-items:stretch!important}
.z-grid-row>*{border-right:1px solid rgba(255,122,132,.42)}
.ope-grid-row>*{border-right:1px solid rgba(112,174,255,.40)}
.demo-grid-row>*{border-right:1px solid rgba(81,220,146,.40)}
.z-grid-row>*:last-child,.ope-grid-row>*:last-child,.demo-grid-row>*:last-child{border-right:0}
.stream-zabbix .stream-row:not(:last-child){border-bottom:1px solid rgba(255,122,132,.46)!important}
.stream-ope .stream-row:not(:last-child){border-bottom:1px solid rgba(112,174,255,.44)!important}
.stream-demo .stream-row:not(:last-child){border-bottom:1px solid rgba(81,220,146,.44)!important}

/* células: alinhamento e leitura à distância */
.grid-cell{min-width:0;display:flex;align-items:center;padding:7px 10px;overflow:hidden}
.grid-cell.center{justify-content:center;text-align:center}
.grid-cell.stack{flex-direction:column;align-items:flex-start;justify-content:center;gap:5px}
.grid-cell .important-host{font-size:12.7px!important;font-weight:700!important;color:#fff!important}
.grid-cell .important-summary{font-size:11.2px!important;font-weight:600!important;line-height:1.2;color:#fff!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block;width:100%}
.grid-cell .jira-key{width:auto!important;flex:0 0 auto!important;font-size:12px!important;font-weight:700!important;padding:0!important;margin:0!important;border:0!important}
.grid-cell .row-time{font-size:9.5px!important;font-weight:600!important;color:#f1f5f8!important;text-align:center;line-height:1.25;white-space:normal!important}
.grid-cell .sev-chip,.grid-cell .status-chip{font-size:8px!important;font-weight:700!important;max-width:100%;height:auto;min-height:20px;line-height:1.15;padding:4px 7px;text-align:center;white-space:normal}
.grid-cell .meta-line{min-width:0;width:100%;font-size:8.8px;color:#d8e3e9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.grid-cell .meta-line strong{font-size:9.2px;font-weight:700;color:#fff}
.grid-cell .mini-tags{display:flex;align-items:center;gap:6px;min-width:0;max-width:100%}
.grid-cell .tag-chip{height:18px;font-size:7.8px!important}
.z-grid-row .z-icon{align-self:center;justify-self:center;margin:auto;border-right:1px solid rgba(255,122,132,.42)}
.empty-row{padding:0!important}

@media(max-width:1400px){
  .column-head{font-size:7.8px}
  .z-column-head,.z-grid-row{grid-template-columns:36px minmax(108px,1.10fr) minmax(165px,1.75fr) 100px 84px!important}
  .ope-column-head,.ope-grid-row{grid-template-columns:84px minmax(195px,1fr) 98px 100px!important}
  .demo-column-head,.demo-grid-row{grid-template-columns:84px minmax(205px,1.35fr) minmax(145px,.80fr) 98px 116px!important}
  .grid-cell{padding:6px 8px}.grid-cell .important-host{font-size:11.5px!important}.grid-cell .important-summary{font-size:10.2px!important}.grid-cell .jira-key{font-size:11px!important}
}


/* ===== V31 | SOMENTE TABELA DEMO — CENTRALIZAÇÃO E ALINHAMENTO ===== */
/* Cabeçalhos centralizados dentro das cinco colunas */
.demo-column-head>span{
  justify-content:center!important;
  text-align:center!important;
  padding-left:8px!important;
  padding-right:8px!important;
}
/* Todas as células da lista verde ficam centralizadas sem alterar larguras/grade */
.stream-demo .demo-grid-row>.grid-cell{
  justify-content:center!important;
  align-items:center!important;
  text-align:center!important;
  padding-left:8px!important;
  padding-right:8px!important;
}
/* Colunas em pilha: atribuído + prioridade/tipo alinhados no mesmo eixo central */
.stream-demo .demo-grid-row>.grid-cell.stack{
  align-items:center!important;
  justify-content:center!important;
}
.stream-demo .demo-grid-row .jira-key{
  width:100%!important;
  text-align:center!important;
}
.stream-demo .demo-grid-row .important-summary{
  width:100%!important;
  text-align:center!important;
}
.stream-demo .demo-grid-row .meta-line{
  width:100%!important;
  text-align:center!important;
}
.stream-demo .demo-grid-row .mini-tags{
  width:100%!important;
  justify-content:center!important;
}
.stream-demo .demo-grid-row .row-time{
  width:100%!important;
  text-align:center!important;
}
.stream-demo .demo-grid-row .status-chip{
  margin-left:auto!important;
  margin-right:auto!important;
}


/* ===== V32 | TV — MAIS ÁREA PARA LISTAS, 6 ITENS E LEITURA À DISTÂNCIA ===== */
/* Header e KPIs ficam mais compactos; estilo e conteúdo permanecem os mesmos */
.noc-header{height:50px!important;padding-bottom:6px!important}
.noc-demo-center{height:42px!important}.noc-demo-logo{width:96px!important;max-height:38px!important}
.noc-clock{height:34px!important;min-width:190px!important}
.noc-brand b{font-size:18px!important}
.noc-kpis{height:94px!important;padding:8px 0 8px!important}
.noc-kpi{height:78px!important;padding-left:62px!important;padding-right:62px!important}
.kpi-icon{left:12px!important;width:48px!important;height:48px!important}.kpi-icon svg{width:29px!important;height:29px!important}
.kpi-body span{font-size:9.5px!important}.kpi-body strong{font-size:26px!important;margin-top:2px!important}.kpi-body small{font-size:8.5px!important;margin-top:3px!important}

/* Reduz apenas a altura analítica para devolver espaço às listas */
.analytics-grid{height:164px!important;padding-top:8px!important}
.analytics-card{padding:10px 12px!important}.analytics-head{padding-bottom:4px!important}
