/* ===== V33 | RESPONSIVO AO TAMANHO REAL DO PAINEL GRAFANA =====
   Mantém o visual V32; remove dependência de altura fixa e faz a composição
   ocupar exatamente o espaço disponível, inclusive em TV/zoom diferentes. */
html,body,#host{width:100%!important;height:100%!important;min-width:0!important;min-height:0!important;overflow:hidden!important}
#host{container-type:size}
.noc-dash{
  width:100%!important;
  height:100%!important;
  min-width:0!important;
  min-height:0!important;
  padding:clamp(7px,1.25cqh,15px) clamp(8px,1cqw,18px) clamp(7px,1.25cqh,16px)!important;
  display:grid!important;
  grid-template-rows:clamp(38px,6.5cqh,50px) clamp(68px,12cqh,94px) minmax(0,1fr) clamp(112px,19cqh,164px)!important;
  overflow:hidden!important;
}
.noc-header,.noc-kpis,.streams-grid,.analytics-grid{height:100%!important;min-height:0!important;min-width:0!important}
.noc-header{padding:0 2px clamp(4px,.7cqh,6px)!important}
