.noc-kpis{padding:clamp(4px,.75cqh,8px) 0!important;gap:clamp(5px,.55cqw,10px)!important;align-items:stretch!important}
.noc-kpi{height:auto!important;min-height:0!important;padding:clamp(5px,.7cqh,10px) clamp(44px,3.4cqw,62px)!important}
