.kpi-icon svg{width:62%!important;height:62%!important}
.kpi-body span{font-size:clamp(7px,.50cqw,9.5px)!important}
.kpi-body strong{font-size:clamp(19px,1.38cqw,26px)!important;margin-top:clamp(0px,.2cqh,2px)!important}
.kpi-body small{font-size:clamp(6.7px,.46cqw,8.5px)!important;margin-top:clamp(1px,.35cqh,3px)!important}

.streams-grid{height:100%!important;min-height:0!important;grid-template-columns:minmax(0,1.02fr) minmax(0,.99fr) minmax(0,1.10fr)!important;gap:clamp(5px,.55cqw,10px)!important;overflow:hidden!important}
.stream-card{height:100%!important;min-height:0!important;grid-template-rows:clamp(34px,5cqh,44px) clamp(24px,3.6cqh,32px) minmax(0,1fr)!important}
.stream-head{padding:0 clamp(8px,.7cqw,13px)!important}
.stream-head strong{font-size:clamp(10px,.72cqw,14px)!important}
.stream-head span{font-size:clamp(7px,.52cqw,10px)!important}
.column-head{height:auto!important;min-height:0!important;font-size:clamp(6.4px,.45cqw,8.8px)!important}
.column-head>span{padding:0 clamp(4px,.45cqw,9px)!important}
.stream-list{min-height:0!important;height:100%!important;grid-template-rows:repeat(6,minmax(0,1fr))!important;overflow:hidden!important}
.stream-row{min-height:0!important;height:auto!important;overflow:hidden!important}
.grid-cell{min-width:0!important;min-height:0!important;padding:clamp(3px,.75cqh,8px) clamp(4px,.48cqw,9px)!important;overflow:hidden!important}

/* Colunas fluidas: as mesmas colunas, sem mínimos que estouram o painel */
.z-column-head,.z-grid-row{grid-template-columns:clamp(28px,2.1cqw,38px) minmax(0,1.18fr) minmax(0,1.90fr) minmax(70px,.92fr) minmax(58px,.70fr)!important}
.ope-column-head,.ope-grid-row{grid-template-columns:minmax(62px,.78fr) minmax(0,2.25fr) minmax(72px,.90fr) minmax(68px,.88fr)!important}
.demo-column-head,.demo-grid-row{grid-template-columns:minmax(62px,.70fr) minmax(0,2.05fr) minmax(0,1.42fr) minmax(72px,.88fr) minmax(76px,.98fr)!important}

.grid-cell .important-host{font-size:clamp(9.8px,.70cqw,13.8px)!important;line-height:1.12!important}
.grid-cell .important-summary{font-size:clamp(8.8px,.62cqw,12px)!important;line-height:1.18!important}
.grid-cell .jira-key{font-size:clamp(9.8px,.66cqw,13px)!important;line-height:1.12!important}
.grid-cell .row-time{font-size:clamp(7.4px,.52cqw,10px)!important;line-height:1.16!important}
.grid-cell .meta-line{font-size:clamp(6.7px,.46cqw,9.3px)!important;line-height:1.12!important}
.grid-cell .meta-line strong{font-size:clamp(7.2px,.50cqw,10px)!important}
.grid-cell .sev-chip,.grid-cell .status-chip{font-size:clamp(6.5px,.45cqw,8.7px)!important;min-height:clamp(17px,2.6cqh,22px)!important;padding:clamp(2px,.35cqh,4px) clamp(4px,.4cqw,8px)!important}
.grid-cell .tag-chip{font-size:clamp(6.2px,.43cqw,8.4px)!important;height:clamp(15px,2.3cqh,19px)!important;padding:0 clamp(4px,.35cqw,7px)!important}
