.analytics-grid{height:100%!important;min-height:0!important;padding-top:clamp(5px,.8cqh,8px)!important;gap:clamp(5px,.55cqw,10px)!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;overflow:hidden!important}
.analytics-card{min-height:0!important;height:100%!important;padding:clamp(6px,.85cqh,10px) clamp(7px,.65cqw,12px)!important}
.analytics-head{padding-bottom:clamp(2px,.45cqh,4px)!important}
.analytics-head strong{font-size:clamp(8.5px,.60cqw,11.5px)!important}
.analytics-head span{font-size:clamp(6.7px,.45cqw,9px)!important}
.bar-list{min-height:0!important;height:calc(100% - clamp(18px,3cqh,28px))!important}
.bar-row{grid-template-columns:minmax(68px,1.12fr) minmax(48px,1fr) clamp(44px,4.2cqw,72px)!important;gap:clamp(3px,.38cqw,7px)!important;min-height:0!important}
.bar-name{font-size:clamp(7px,.48cqw,9px)!important;gap:clamp(3px,.35cqw,7px)!important}
.bar-name i{width:clamp(5px,.42cqw,8px)!important;height:clamp(5px,.42cqw,8px)!important}
.bar-track{height:clamp(5px,1cqh,8px)!important}
.bar-row b{font-size:clamp(6.8px,.47cqw,9px)!important}

