function rows(ref){return F.filter(f=>String(f.refId||"")==ref).flatMap(f=>{let c=(f.fields||[]).map(x=>[x.name,V(x.values)]),n=Math.max(0,...c.map(x=>x[1].length));return Array.from({length:n},(_,i)=>Object.fromEntries(c.map(x=>[x[0],x[1][i]])))})}
function p(o,ns){let e=Object.entries(o||{});for(const n of ns){let x=e.find(([k])=>N(k)==N(n));if(x&&x[1]!=null&&x[1]!=="")return x[1]}return""}
function dt(v){if(v==null||v==="")return"N/D";let n=Number(v),d;if(Number.isFinite(n)){if(n<946684800)return"N/D";d=new Date(n<1e12?n*1000:n)}else d=new Date(v);if(isNaN(d))return"N/D";const z=x=>String(x).padStart(2,"0");return `${z(d.getDate())}/${z(d.getMonth()+1)}/${d.getFullYear()} ${z(d.getHours())}:${z(d.getMinutes())}:${z(d.getSeconds())}`}
function flatten(obj,out={},prefix=""){if(!obj||typeof obj!=="object"||obj instanceof Date)return out;for(const [k,v] of Object.entries(obj)){let key=prefix?prefix+"."+k:k;if(v&&typeof v==="object"&&!Array.isArray(v)){flatten(v,out,key)}else if(v!=null&&v!==""){out[key]=v;if(out[k]==null)out[k]=v}}return out}
function alertRows(ref){let all=[];for(const f of F.filter(x=>String(x.refId||"")==ref)){let base={};if(f.name)base.frameName=f.name;if(f.meta)flatten(f.meta,base,"meta");let fields=f.fields||[],n=Math.max(1,...fields.map(x=>V(x.values).length));for(let i=0;i<n;i++){let r={...base};for(const fld of fields){if(fld.labels)Object.assign(r,flatten(fld.labels,{},"labels"));if(fld.config)flatten(fld.config,r,"config");let a=V(fld.values),v=a[i];r[fld.name]=v;if(v&&typeof v==="object")flatten(v,r)}all.push(r)}}return all}
function sev(x){let v=p(x,["severity","priority","triggerSeverity","labels.severity","labels.priority","config.custom.severity"]),n=Number(v),t=N(v);if(n===5||t.includes("disaster")||t.includes("desastre"))return 5;if(n===4||t.includes("high")||t.includes("alto"))return 4;if(n===3||t.includes("average")||t.includes("media"))return 3;return 4}
