function alertView(x){let host="";for(const c of [p(x,["host"]),p(x,["hostname"]),p(x,["host.name"]),p(x,["host_name"]),p(x,["hostName"]),p(x,["Host"]),p(x,["labels.host"]),p(x,["labels.hostname"]),p(x,["server"]),p(x,["servidor"]),p(x,["apresentador"])]){const s=hostText(c);if(s){host=s;break}}if(!host){for(const [k,v] of Object.entries(x||{})){const nk=N(k);if(nk.includes("host")||nk.includes("server")||nk.includes("apresentador")){const s=hostText(v);if(s){host=s;break}}}}let problem=firstGood(x,["name","problem","description","trigger","triggerName","trigger.name","eventName","labels.name","labels.problem","labels.trigger","frameName"]);let lc=p(x,["lastchange","lastChange","clock","timestamp","Time","time"]);return{host:host||"N/D",problem:problem||"N/D",lastchange:lc,severity:sev(x)}}

