function toMs(v){if(v==null||v==="")return NaN;const n=Number(v);if(Number.isFinite(n)){if(n<946684800)return NaN;return n<1e12?n*1000:n}const d=new Date(v);return isNaN(d)?NaN:d.getTime()}
function fmtDuration(ms){if(!Number.isFinite(ms)||ms<0)return"N/D";const mins=Math.round(ms/60000),h=Math.floor(mins/60),m=mins%60;return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}`}
