function countBy(arr,fn){const m={};for(const x of arr){const k=String(fn(x)||"NÃO INFORMADO").trim()||"NÃO INFORMADO";m[k]=(m[k]||0)+1}return m}
function ordered(obj,preferred=[]){const entries=Object.entries(obj);return entries.sort((a,b)=>{const ai=preferred.indexOf(U(a[0])),bi=preferred.indexOf(U(b[0]));if(ai>=0||bi>=0){if(ai<0)return 1;if(bi<0)return-1;if(ai!==bi)return ai-bi}return b[1]-a[1]})}
function renderBars(sel,total,entries,colorFn){
